import{_ as d,o as e,c as o,a2 as c}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Coverage baseline — 2026-07-11","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/coverage/baseline-2026-07-11.md","filePath":"quality-reports/coverage/baseline-2026-07-11.md"}'),a={name:"quality-reports/coverage/baseline-2026-07-11.md"};function r(s,t,i,n,l,h){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="coverage-baseline-—-2026-07-11" tabindex="-1">Coverage baseline — 2026-07-11 <a class="header-anchor" href="#coverage-baseline-—-2026-07-11" aria-label="Permalink to &quot;Coverage baseline — 2026-07-11&quot;">​</a></h1><p>Real coverage numbers across every <code>packages/*</code> after two changes to how coverage is measured.</p><ul><li>The 21 packages whose <code>test:cov</code> narrowed the include to a hand-written list of specific files now use the glob <code>.vitest-dist/src/**/*.js</code>. What the file used to show was <code>100%</code> line coverage of a shrinking include list. <code>orm</code> slipped through the first pass; codex-review on the PR caught it and it was fixed in the same PR.</li><li>The 9 packages that had no <code>test:cov</code> script (<code>agent</code>, <code>component</code>, <code>desktop</code>, <code>lean</code>, <code>mcp</code>, <code>mobile</code>, <code>payment</code>, <code>search</code>, <code>security-devsecops</code>) got one, matching the pattern the rest of the repo already used, and picked up <code>@vitest/coverage-v8</code> as a devDependency.</li></ul><p>Every <code>test:cov</code> matches <code>.vitest-dist/src/**/*.js</code>, excluding <code>.vitest-dist/tests/**</code>. Nothing else is excluded. <code>**/types.js</code> was briefly excluded in an earlier round of this PR to strip empty-stub noise from type-only <code>.ts</code> files; codex-adversarial pointed out that many <code>types.ts</code> files also export runtime values (<code>export function providerEventName</code> in <code>payment/src/semantics/types.ts</code>, <code>export class Eip1193Error</code> in <code>dapp/src/types.ts</code>, and similar in ten more packages), so that exclusion was hiding real code and it was reverted.</p><p>Numbers are <code>line% | branch% | function%</code>, sorted by line coverage ascending.</p><table tabindex="0"><thead><tr><th>#</th><th>package</th><th>line</th><th>branch</th><th>function</th></tr></thead><tbody><tr><td>1</td><td><code>ui</code></td><td>34.15</td><td>82.60</td><td>39.13</td></tr><tr><td>2</td><td><code>cli</code></td><td>65.63</td><td>94.37</td><td>93.54</td></tr><tr><td>3</td><td><code>dapp</code></td><td>66.87</td><td>78.26</td><td>70.34</td></tr><tr><td>4</td><td><code>cache</code></td><td>68.09</td><td>85.71</td><td>85.41</td></tr><tr><td>5</td><td><code>e2e</code></td><td>71.11</td><td>64.44</td><td>81.81</td></tr><tr><td>6</td><td><code>perf-harness</code></td><td>75.32</td><td>77.50</td><td>88.23</td></tr><tr><td>7</td><td><code>queue</code></td><td>78.03</td><td>84.24</td><td>82.50</td></tr><tr><td>8</td><td><code>orm</code></td><td>83.68</td><td>83.30</td><td>94.26</td></tr><tr><td>9</td><td><code>api</code></td><td>88.58</td><td>84.78</td><td>96.00</td></tr><tr><td>10</td><td><code>cli-test</code></td><td>92.05</td><td>86.11</td><td>94.44</td></tr><tr><td>11</td><td><code>realtime</code></td><td>92.94</td><td>86.01</td><td>84.29</td></tr><tr><td>12</td><td><code>agent</code></td><td>93.38</td><td>85.98</td><td>95.12</td></tr><tr><td>13</td><td><code>release-invariants</code></td><td>94.69</td><td>90.47</td><td>80.00</td></tr><tr><td>14</td><td><code>streaming</code></td><td>95.45</td><td>84.02</td><td>88.70</td></tr><tr><td>15</td><td><code>mcp</code></td><td>95.63</td><td>89.10</td><td>92.72</td></tr><tr><td>16</td><td><code>auth</code></td><td>95.68</td><td>84.08</td><td>93.79</td></tr><tr><td>17</td><td><code>quality-metrics</code></td><td>95.83</td><td>89.64</td><td>100.00</td></tr><tr><td>18</td><td><code>component</code></td><td>96.09</td><td>92.06</td><td>96.69</td></tr><tr><td>19</td><td><code>ai-llm</code></td><td>96.52</td><td>80.15</td><td>94.00</td></tr><tr><td>20</td><td><code>search</code></td><td>96.84</td><td>89.03</td><td>99.00</td></tr><tr><td>21</td><td><code>fresh</code></td><td>97.51</td><td>92.41</td><td>91.22</td></tr><tr><td>22</td><td><code>mobile</code></td><td>97.89</td><td>92.49</td><td>98.94</td></tr><tr><td>23</td><td><code>observability</code></td><td>97.90</td><td>92.49</td><td>99.08</td></tr><tr><td>24</td><td><code>hono</code></td><td>97.91</td><td>88.64</td><td>97.75</td></tr><tr><td>25</td><td><code>astro</code></td><td>97.92</td><td>91.80</td><td>90.69</td></tr><tr><td>26</td><td><code>security</code></td><td>97.97</td><td>91.94</td><td>99.25</td></tr><tr><td>27</td><td><code>core</code></td><td>97.98</td><td>92.47</td><td>93.33</td></tr><tr><td>28</td><td><code>visual</code></td><td>98.14</td><td>82.75</td><td>80.00</td></tr><tr><td>29</td><td><code>desktop</code></td><td>98.26</td><td>93.14</td><td>99.21</td></tr><tr><td>30</td><td><code>payment</code></td><td>98.46</td><td>92.85</td><td>99.35</td></tr><tr><td>31</td><td><code>nextjs</code></td><td>99.44</td><td>96.04</td><td>100.00</td></tr><tr><td>32</td><td><code>lean</code></td><td>99.47</td><td>95.71</td><td>98.36</td></tr><tr><td>33</td><td><code>data</code></td><td>99.50</td><td>97.29</td><td>95.65</td></tr><tr><td>34</td><td><code>remix</code></td><td>99.65</td><td>92.13</td><td>100.00</td></tr><tr><td>35</td><td><code>a11y</code></td><td>99.71</td><td>92.72</td><td>95.23</td></tr><tr><td>36</td><td><code>edge</code></td><td>99.90</td><td>97.85</td><td>100.00</td></tr><tr><td>37</td><td><code>security-devsecops</code></td><td>99.90</td><td>96.03</td><td>97.95</td></tr><tr><td>38</td><td><code>nuxt</code></td><td>100.00</td><td>98.93</td><td>100.00</td></tr><tr><td>39</td><td><code>qwikcity</code></td><td>100.00</td><td>100.00</td><td>100.00</td></tr><tr><td>40</td><td><code>solidjs</code></td><td>100.00</td><td>97.61</td><td>100.00</td></tr><tr><td>41</td><td><code>solidstart</code></td><td>100.00</td><td>97.43</td><td>100.00</td></tr><tr><td>42</td><td><code>sveltekit</code></td><td>100.00</td><td>92.92</td><td>97.72</td></tr></tbody></table><p>Only <code>qwikcity</code> is at 100/100/100. Four more sit at 100% line but not 100% branch or function — the sort ranks these by branch on the tie. Every other package has either lines the tests never reach, or branches they only reach through one arm, or exported functions the tests never call, or all three.</p><p>The target is 100% line, 100% branch, 100% function across every package. Each row below the top is a follow-up.</p><h2 id="what-measured-means-now" tabindex="-1">What &quot;measured&quot; means now <a class="header-anchor" href="#what-measured-means-now" aria-label="Permalink to &quot;What &quot;measured&quot; means now&quot;">​</a></h2><p>Before this baseline, the numbers this file reported were misleading in two ways.</p><ul><li><code>test:cov</code> for 21 packages had shrunk to a hand-written list of <code>.vitest-dist/src/&lt;file&gt;.js</code> includes. Anything not on the list was outside the fraction, so a package could show <code>100%</code> while a 466-line file (<code>packages/a11y/src/layer-harness.ts</code>, before this change) was never counted. <code>observability</code> measured 6 of 30 source files; <code>dapp</code> measured 7 of 25. <code>orm</code> measured a wide slice through a <code>semantics/**/*.js</code> glob but still hand-listed the three root files, missing anything new added later at the root.</li><li>9 packages had no <code>test:cov</code> script at all. There were no numbers, so there was nothing to look at. <code>payment</code>, <code>desktop</code>, <code>mobile</code>, <code>security-devsecops</code> all fall into this group.</li></ul><p>After this change, every package&#39;s <code>test:cov</code> matches <code>.vitest-dist/src/**/*.js</code> and excludes <code>.vitest-dist/tests/**</code>. The percentages are what the tests actually cover.</p><h2 id="two-ways-to-close-a-gap" tabindex="-1">Two ways to close a gap <a class="header-anchor" href="#two-ways-to-close-a-gap" aria-label="Permalink to &quot;Two ways to close a gap&quot;">​</a></h2><p>Some gaps close by writing new tests; some close by removing dead code. Neither is a shortcut for the other.</p><p>The <code>ui</code> result is the extreme case. <code>ui/src</code> has ten files. Every test file drives one component; five components have no tests at all. Adding tests, not adjusting the include, closes it.</p><p>The <code>qwikcity</code> result is the other end: three source files, three test files, every branch reached, every function called. Adding another component to <code>qwikcity</code> without adding its tests would put it back on this list.</p><h2 id="follow-ups" tabindex="-1">Follow-ups <a class="header-anchor" href="#follow-ups" aria-label="Permalink to &quot;Follow-ups&quot;">​</a></h2><p>Each row below the target becomes its own follow-up. The order below is coverage-ascending; the reason is that a 34% package takes many more tests to close than a 99.5% package, and the small deltas are easier to schedule against a busy week.</p><ol><li><code>ui</code> (34.15) — the largest single gap in the repository.</li><li><code>cli</code>, <code>dapp</code>, <code>cache</code>, <code>e2e</code>, <code>perf-harness</code>, <code>queue</code> (&lt;80%).</li><li><code>orm</code>, <code>api</code>, <code>cli-test</code>, <code>realtime</code>, <code>agent</code>, <code>release-invariants</code>, <code>streaming</code>, <code>mcp</code>, <code>auth</code>, <code>quality-metrics</code>, <code>component</code>, <code>ai-llm</code>, <code>search</code> (80–97%).</li><li>Everything else 97–99% — small deltas per file; several packages need only a handful of tests.</li><li><code>nuxt</code>, <code>solidjs</code>, <code>solidstart</code>, <code>sveltekit</code> — 100% line but not 100% branch or function. One test per uncovered arm.</li></ol>',19)])])}const m=d(a,[["render",r]]);export{u as __pageData,m as default};
